CREATE TABLE IF NOT EXISTS schema_migrations (version INT PRIMARY KEY, sha512 CHAR(128) CHARACTER SET ascii NOT NULL, applied_at DATETIME(6) NOT NULL DEFAULT (UTC_TIMESTAMP(6)));
CREATE TABLE IF NOT EXISTS workspace_identity (id INT PRIMARY KEY, data_root TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS assets (sha512 CHAR(128) CHARACTER SET ascii PRIMARY KEY, source_path TEXT NOT NULL, bytes BIGINT UNSIGNED NOT NULL, created_at DATETIME(6) NOT NULL DEFAULT (UTC_TIMESTAMP(6)));
CREATE TABLE IF NOT EXISTS acquisitions (id VARCHAR(64) PRIMARY KEY, asset_sha512 CHAR(128) CHARACTER SET ascii NULL, kind ENUM('local','download') NOT NULL, retry_of VARCHAR(64) NULL, state ENUM('RUNNING','SUCCEEDED','FAILED','INTERRUPTED') NOT NULL, receipt_path TEXT NOT NULL, created_at DATETIME(6) NOT NULL DEFAULT (UTC_TIMESTAMP(6)), finished_at DATETIME(6) NULL, INDEX(asset_sha512), INDEX(retry_of), FOREIGN KEY(asset_sha512) REFERENCES assets(sha512), FOREIGN KEY(retry_of) REFERENCES acquisitions(id));
CREATE TABLE IF NOT EXISTS runs (id VARCHAR(64) PRIMARY KEY, asset_sha512 CHAR(128) CHARACTER SET ascii NOT NULL, recipe_path TEXT NOT NULL, recipe_hash CHAR(128) CHARACTER SET ascii NOT NULL, state ENUM('RUNNING','SUCCEEDED','FAILED','INTERRUPTED','REVIEW') NOT NULL, bindings_path TEXT NOT NULL, bindings_hash CHAR(128) CHARACTER SET ascii NOT NULL, started_at DATETIME(6) NOT NULL DEFAULT (UTC_TIMESTAMP(6)), finished_at DATETIME(6) NULL, INDEX(asset_sha512,started_at), FOREIGN KEY(asset_sha512) REFERENCES assets(sha512));
CREATE TABLE IF NOT EXISTS executions (id VARCHAR(64) PRIMARY KEY, asset_sha512 CHAR(128) CHARACTER SET ascii NOT NULL, run_id VARCHAR(64) NULL, node VARCHAR(64) NOT NULL, scope VARCHAR(64) NOT NULL, version INT NOT NULL, strategy_id VARCHAR(64) NOT NULL, strategy_version VARCHAR(64) NOT NULL, retry_of VARCHAR(64) NULL, state ENUM('RUNNING','SUCCEEDED','FAILED','INTERRUPTED') NOT NULL, quality_status ENUM('PASS','REVIEW','FAIL') NOT NULL DEFAULT 'REVIEW', request_path TEXT NOT NULL, request_hash CHAR(128) CHARACTER SET ascii NOT NULL, manifest_path TEXT NULL, manifest_hash CHAR(128) CHARACTER SET ascii NULL, started_at DATETIME(6) NOT NULL DEFAULT (UTC_TIMESTAMP(6)), finished_at DATETIME(6) NULL, UNIQUE(asset_sha512,node,scope,version), INDEX(run_id), INDEX(retry_of), INDEX(asset_sha512,state), FOREIGN KEY(asset_sha512) REFERENCES assets(sha512), FOREIGN KEY(run_id) REFERENCES runs(id), FOREIGN KEY(retry_of) REFERENCES executions(id));
CREATE TABLE IF NOT EXISTS artifacts (id VARCHAR(64) PRIMARY KEY, execution_id VARCHAR(64) NOT NULL, relative_path VARCHAR(512) NOT NULL, schema_id VARCHAR(64) NOT NULL, kind VARCHAR(64) NOT NULL, sha512 CHAR(128) CHARACTER SET ascii NOT NULL, bytes BIGINT UNSIGNED NOT NULL, metadata_json JSON NOT NULL, UNIQUE(execution_id,relative_path), INDEX(execution_id,kind), INDEX(schema_id,execution_id), FOREIGN KEY(execution_id) REFERENCES executions(id));
CREATE TABLE IF NOT EXISTS execution_inputs (execution_id VARCHAR(64) NOT NULL, port VARCHAR(64) NOT NULL, ordinal INT NOT NULL, artifact_id VARCHAR(64) NOT NULL, PRIMARY KEY(execution_id,port,ordinal), INDEX(artifact_id), FOREIGN KEY(execution_id) REFERENCES executions(id), FOREIGN KEY(artifact_id) REFERENCES artifacts(id));
CREATE TABLE IF NOT EXISTS artifact_parents (artifact_id VARCHAR(64) NOT NULL, parent_artifact_id VARCHAR(64) NOT NULL, PRIMARY KEY(artifact_id,parent_artifact_id), INDEX(parent_artifact_id), FOREIGN KEY(artifact_id) REFERENCES artifacts(id), FOREIGN KEY(parent_artifact_id) REFERENCES artifacts(id));
CREATE TABLE IF NOT EXISTS selections (id VARCHAR(64) PRIMARY KEY, asset_sha512 CHAR(128) CHARACTER SET ascii NOT NULL, branch VARCHAR(64) NOT NULL, role VARCHAR(64) NOT NULL, artifact_id VARCHAR(64) NOT NULL, reason TEXT NOT NULL, created_at DATETIME(6) NOT NULL DEFAULT (UTC_TIMESTAMP(6)), INDEX(asset_sha512,branch,role,created_at), FOREIGN KEY(asset_sha512) REFERENCES assets(sha512), FOREIGN KEY(artifact_id) REFERENCES artifacts(id));
CREATE TABLE IF NOT EXISTS events (id VARCHAR(64) PRIMARY KEY, asset_sha512 CHAR(128) CHARACTER SET ascii NOT NULL, execution_id VARCHAR(64) NULL, run_id VARCHAR(64) NULL, seq BIGINT UNSIGNED NOT NULL, type VARCHAR(64) NOT NULL, at DATETIME(6) NOT NULL DEFAULT (UTC_TIMESTAMP(6)), payload_json JSON NOT NULL, UNIQUE(asset_sha512,seq), INDEX(execution_id), INDEX(run_id), FOREIGN KEY(asset_sha512) REFERENCES assets(sha512), FOREIGN KEY(execution_id) REFERENCES executions(id), FOREIGN KEY(run_id) REFERENCES runs(id));
CREATE TABLE IF NOT EXISTS releases (id VARCHAR(64) PRIMARY KEY, asset_sha512 CHAR(128) CHARACTER SET ascii NOT NULL, run_id VARCHAR(64) NOT NULL, render_artifact_id VARCHAR(64) NOT NULL, qa_artifact_id VARCHAR(64) NOT NULL, review_artifact_id VARCHAR(64) NOT NULL, manifest_artifact_id VARCHAR(64) NOT NULL, created_at DATETIME(6) NOT NULL DEFAULT (UTC_TIMESTAMP(6)), INDEX(asset_sha512,created_at), FOREIGN KEY(asset_sha512) REFERENCES assets(sha512), FOREIGN KEY(run_id) REFERENCES runs(id), FOREIGN KEY(render_artifact_id) REFERENCES artifacts(id), FOREIGN KEY(qa_artifact_id) REFERENCES artifacts(id), FOREIGN KEY(review_artifact_id) REFERENCES artifacts(id), FOREIGN KEY(manifest_artifact_id) REFERENCES artifacts(id));
